{
  "path": {
    "type": "TEXT",
    "hint": "Full path of the directory, e.g. myindex/dir (the index's top directory is myindex): the index name followed by the path inside the index, the same form gufi_find prints and the gufi_* tools' path arguments accept."
  },
  "dname": {
    "type": "TEXT",
    "hint": "directory name"
  },
  "name": {
    "type": "TEXT",
    "hint": "Base name of the directory only, not a path. Full path: the path column."
  },
  "type": {
    "type": "TEXT",
    "hint": "character d for directory"
  },
  "inode": {
    "type": "TEXT",
    "hint": "inode number from source system"
  },
  "mode": {
    "type": "INT64",
    "hint": "unix mode bits"
  },
  "nlink": {
    "type": "INT64",
    "hint": "unix number of links"
  },
  "uid": {
    "type": "INT64",
    "hint": "unix uid"
  },
  "gid": {
    "type": "INT64",
    "hint": "unix gid"
  },
  "size": {
    "type": "INT64",
    "hint": "unix logical file size in bytes"
  },
  "blksize": {
    "type": "INT64",
    "hint": "unix blksize for file"
  },
  "blocks": {
    "type": "INT64",
    "hint": "unix number of blocks"
  },
  "atime": {
    "type": "INT64",
    "hint": "unix access time epoch"
  },
  "mtime": {
    "type": "INT64",
    "hint": "unix modification time epoch"
  },
  "ctime": {
    "type": "INT64",
    "hint": "unix change time epoch"
  },
  "linkname": {
    "type": "TEXT",
    "hint": "unix string for link name"
  },
  "xattr_names": {
    "type": "BLOB",
    "hint": "concatenation of all extended attributes"
  },
  "crtime": {
    "type": "INT64",
    "hint": "create time epoch (some file systems provide)"
  },
  "totfiles": {
    "type": "INT64",
    "hint": "number files"
  },
  "totlinks": {
    "type": "INT64",
    "hint": "summed links"
  },
  "minuid": {
    "type": "INT64",
    "hint": "min uid"
  },
  "maxuid": {
    "type": "INT64",
    "hint": "max uid"
  },
  "mingid": {
    "type": "INT64",
    "hint": "min gid"
  },
  "maxgid": {
    "type": "INT64",
    "hint": "max gid"
  },
  "minsize": {
    "type": "INT64",
    "hint": "min size"
  },
  "maxsize": {
    "type": "INT64",
    "hint": "max size"
  },
  "totzero": {
    "type": "INT64",
    "hint": "number of zero-size files"
  },
  "totltk": {
    "type": "INT64",
    "hint": "number <= 1024"
  },
  "totmtk": {
    "type": "INT64",
    "hint": "number > 1024"
  },
  "totltm": {
    "type": "INT64",
    "hint": "number <= 1048576"
  },
  "totmtm": {
    "type": "INT64",
    "hint": "number > 1048576"
  },
  "totmtg": {
    "type": "INT64",
    "hint": "number <= 1073741824"
  },
  "totmtt": {
    "type": "INT64",
    "hint": "number > 1073741824"
  },
  "totsize": {
    "type": "INT64",
    "hint": "summed size"
  },
  "minctime": {
    "type": "INT64",
    "hint": "min ctime"
  },
  "maxctime": {
    "type": "INT64",
    "hint": "max ctime"
  },
  "totctime": {
    "type": "INT64",
    "hint": "summed ctime"
  },
  "minmtime": {
    "type": "INT64",
    "hint": "min mtime"
  },
  "maxmtime": {
    "type": "INT64",
    "hint": "max mtime"
  },
  "totmtime": {
    "type": "INT64",
    "hint": "summed mtime"
  },
  "minatime": {
    "type": "INT64",
    "hint": "min atime"
  },
  "maxatime": {
    "type": "INT64",
    "hint": "max atime"
  },
  "totatime": {
    "type": "INT64",
    "hint": "summed atime"
  },
  "minblocks": {
    "type": "INT64",
    "hint": "min blocks"
  },
  "maxblocks": {
    "type": "INT64",
    "hint": "max blocks"
  },
  "totblocks": {
    "type": "INT16",
    "hint": "summed blocks"
  },
  "totxattr": {
    "type": "INT64",
    "hint": "number of files/links with xattrs present"
  },
  "depth": {
    "type": "INT64",
    "hint": "depth (number of slashes in path)"
  },
  "mincrtime": {
    "type": "INT64",
    "hint": "min create time"
  },
  "maxcrtime": {
    "type": "INT64",
    "hint": "max create time"
  },
  "totcrtime": {
    "type": "INT64",
    "hint": "summed create time"
  },
  "minossint1": {
    "type": "INT64",
    "hint": "min ossint1"
  },
  "maxossint1": {
    "type": "INT64",
    "hint": "max ossint1"
  },
  "totossint1": {
    "type": "INT64",
    "hint": "summed ossint1"
  },
  "minossint2": {
    "type": "INT64",
    "hint": "min ossint2"
  },
  "maxossint2": {
    "type": "INT64",
    "hint": "max ossint2"
  },
  "totossint2": {
    "type": "INT64",
    "hint": "summed ossint2"
  },
  "minossint3": {
    "type": "INT64",
    "hint": "min ossint3"
  },
  "maxossint3": {
    "type": "INT64",
    "hint": "max ossint3"
  },
  "totossint3": {
    "type": "INT64",
    "hint": "summed ossint3"
  },
  "minossint4": {
    "type": "INT64",
    "hint": "min ossint4"
  },
  "maxossint4": {
    "type": "INT64",
    "hint": "max ossint4"
  },
  "totossint4": {
    "type": "INT64",
    "hint": "summed ossint4"
  },
  "rectype": {
    "type": "INT64",
    "hint": "0 for total for entire dir 1 for totals by user 2 for totals by group"
  },
  "pinode": {
    "type": "TEXT",
    "hint": "parent directory inode"
  },
  "isroot": {
    "type": "INT64",
    "hint": "(used for rollup)"
  },
  "canrollup": {
    "type": "INT64",
    "hint": "(used for rollup) can rollup"
  },
  "isrolledup": {
    "type": "INT64",
    "hint": "(used for rollup) is rolled up"
  }
}
